        if (!isDict (raw)) { return; }
        this->info = typedsupport::getAny (raw, "info");
        for (const auto& kv : std::any_cast<dict> (raw).entries ()) {
            if (kv.first == "info") { continue; }
            this->predictionTickers.emplace (kv.first, PredictionTicker (kv.second));
        }
